MARK0, MARK1 = "<!-- further-options -->", "<!-- /further-options -->"
for lang in LANGS:
    f = root / ("README.md" if lang == "en" else f"README.{lang}.md")
    t = f.read_text(encoding="utf8")
    body = [MARK0, f"## {TITLE[lang]}", "", INTRO[lang], ""]
    for opts, d in G:
        body.append(f"- {opts}: {d[lang]}")
    body += ["", MARK1, ""]
    block = "\n".join(body)
    if MARK0 in t:
        t = re.sub(re.escape(MARK0) + r".*?" + re.escape(MARK1) + r"\n?", lambda m: block, t, flags=re.S)
    else:
        i = t.index("\n## ", t.index("\n## ") + 1) if False else None
        # insert before the first heading that follows the "less common options" section
        m = re.search(r"^## (?:Install|Instalare|Installation|Instalación|Installazione|Instalação|Telepítés)\b", t, re.M)
        if not m: raise SystemExit(f"{f}: install heading not found")
        t = t[:m.start()] + block + "\n" + t[m.start():]
    f.write_text(t, encoding="utf8")
    print("wrote", f.name)
